/* Demonstrates using unlinkat() to safely remove a file relative to an open directory FD. */
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <errno.h>
#include <string.h>

#define DIR_PATH "test_dir_unlink"
#define FILE_NAME "temp_file_to_remove.txt"

void cleanup(int fd) {
    if (fd != -1) close(fd);
    rmdir(DIR_PATH);
}

int main() {
    int dirfd = -1;
    char full_path[100];

    // 1. Setup: Create a directory and a file inside it
    if (mkdir(DIR_PATH, 0755) == -1) {
        if (errno != EEXIST) { perror("mkdir"); return EXIT_FAILURE; }
    }

    snprintf(full_path, sizeof(full_path), "%s/%s", DIR_PATH, FILE_NAME);
    if (creat(full_path, 0644) == -1) { perror("creat"); cleanup(dirfd); return EXIT_FAILURE; }

    // 2. Open the directory to get the file descriptor (dirfd)
    dirfd = open(DIR_PATH, O_RDONLY | O_DIRECTORY);
    if (dirfd == -1) { perror("open dir"); cleanup(-1); return EXIT_FAILURE; }

    printf("Attempting to unlink '%s' using dirfd %d...
", FILE_NAME, dirfd);

    // 3. Use unlinkat to remove the file name relative to dirfd
    // flags = 0 (treats it as unlink(2) for a file)
    if (unlinkat(dirfd, FILE_NAME, 0) == 0) {
        printf("Success: File '%s' removed.\n", FILE_NAME);
    } else {
        fprintf(stderr, "Error unlinking file: %s\n", strerror(errno));
        cleanup(dirfd);
        return EXIT_FAILURE;
    }

    // 4. Cleanup: Close the descriptor and remove the now-empty directory
    cleanup(dirfd);
    printf("Cleanup complete.\n");
    return EXIT_SUCCESS;
}
